head.b:skin:
    /*==================================================================
  PHOENIX THEME DESIGNER VARIABLES
====================================================================

<Group description="Phoenix Theme Colors" selector="body">

<Variable name="phoenix.primary.color"
          description="Primary Accent Color"
          type="color"
          default="#9A7847"
          value="#9A7847"/>

<Variable name="phoenix.primary.dark"
          description="Primary Accent Hover"
          type="color"
          default="#765A34"
          value="#765A34"/>

<Variable name="phoenix.secondary.color"
          description="Secondary Color"
          type="color"
          default="#252525"
          value="#252525"/>

<Variable name="phoenix.background.color"
          description="Page Background"
          type="color"
          default="#F5F4F1"
          value="#F5F4F1"/>

<Variable name="phoenix.surface.color"
          description="Card Background"
          type="color"
          default="#ffffff"
          value="#ffffff"/>

<Variable name="phoenix.text.color"
          description="Primary Text"
          type="color"
          default="#2b2b2b"
          value="#2b2b2b"/>

<Variable name="phoenix.text.muted"
          description="Secondary Text"
          type="color"
          default="#6c757d"
          value="#6c757d"/>

<Variable name="phoenix.border.color"
          description="Border Color"
          type="color"
          default="#e9ecef"
          value="#e9ecef"/>

</Group>

<Group description="Phoenix Typography" selector="body">

<Variable
    name="phoenix.brand.font"
    description="Brand Font"
    type="font"
    default="normal normal 700 30px Tajawal, sans-serif"
    value="normal normal 700 30px Tajawal, sans-serif"/>

<Variable
    name="phoenix.heading.font"
    description="Heading Font"
    type="font"
    default="normal normal 700 48px Tajawal, sans-serif"
    value="normal normal 700 48px Tajawal, sans-serif"/>

<Variable
    name="phoenix.body.font"
    description="Body Font"
    type="font"
    default="normal normal 16px IBM Plex Sans Arabic, sans-serif"
    value="normal normal 16px IBM Plex Sans Arabic, sans-serif"/>

<Variable
    name="phoenix.ui.font"
    description="UI Font"
    type="font"
    default="normal normal 16px IBM Plex Sans Arabic, sans-serif"
    value="normal normal 16px IBM Plex Sans Arabic, sans-serif"/>

</Group>

*/
    /* ==========================================================================
       VARIABLES, RESET, & BASE STYLES
       ========================================================================== */
    :root {

    --primary-color: $(phoenix.primary.color);
    --primary-dark: $(phoenix.primary.dark);
    --secondary-color: $(phoenix.secondary.color);

    --bg-color: $(phoenix.background.color);
    --card-bg: $(phoenix.surface.color);

    --text-color: $(phoenix.text.color);
    --text-muted: $(phoenix.text.muted);

    --border-color: $(phoenix.border.color);

    --font-sans: $(phoenix.body.font);

    --max-width: 1200px;

    --transition: all 0.3s cubic-bezier(0.4,0,0.2,1);

    --shadow: 0 4px 6px -1px rgba(0,0,0,.1),
              0 2px 4px -1px rgba(0,0,0,.06);

    --shadow-lg: 0 10px 15px -3px rgba(0,0,0,.1),
                 0 4px 6px -2px rgba(0,0,0,.05);

    /* Compatibility Layer */

    --primary: var(--primary-color);

    --surface: var(--card-bg);

    --surface-alt: var(--bg-color);

    --text: var(--text-color);

    --text-light: var(--text-muted);

    --border: var(--border-color);

    --font: var(--font-sans);

    --font-brand: $(phoenix.brand.font);

    --font-heading: $(phoenix.heading.font);

    --font-body: $(phoenix.body.font);

    --font-ui: $(phoenix.ui.font);

    --shadow-sm: var(--shadow);

    --shadow-md: var(--shadow-lg);

}

    * {
        box-sizing: border-box;
        margin: 0;
        padding: 0;
    }

    body {
        font: var(--font-body);
        background-color: var(--surface-alt);
        color: var(--text);
        line-height: 1.6;
        overflow-x: hidden;
    }

    a {
        color: inherit;
        text-decoration: none;
        transition: var(--transition);
    }

    img {
        max-width: 100%;
        height: auto;
    }

    /* Container Utility */
    .container {
        width: 100%;
        max-width: var(--max-width);
        margin: 0 auto;
        padding: 0 24px;
    }

    .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
    }

    .skip-link {
        position: absolute;
        top: -100px;
        left: 20px;
        background: var(--primary);
        color: #ffffff;
        padding: 10px 20px;
        z-index: 9999;
        font-weight: 600;
        border-radius: 4px;
        transition: top 0.2s;
    }
    .skip-link:focus {
        top: 20px;
    }

    /* ==========================================================================
       MODERN NAVIGATION & HEADER (FLEXBOX)
       ========================================================================== */
    .navbar {
        background: var(--surface);
        border-bottom: 1px solid var(--border);
        position: relative;
        top: 0;
        z-index: 1000;
        padding: 16px 0;
    }
    .navbar .header,
    .navbar .main-menu-section,
    .navbar .widget {
        margin: 0;
        padding: 0;
        min-height: 0;
    }
    .nav-container {
        display: flex;
        justify-content: space-between;
        align-items: center;
    }
    .logo {
        font: var(--font-brand);
        font-size: 30px;
        font-weight: 800;
        color: var(--text);
        letter-spacing: -0.03em;
        white-space: nowrap;
    }
    .logo span {
        color: var(--primary);
    }
    .site-navigation {
        display: flex;
        align-items: center;
        position: relative;
        z-index: 99;
    }
    .nav-menu {
       display: flex;
       gap: 1.5rem;
       list-style: none;
       margin: 0;
       padding: 0px 0px 0px 25px;
       position: relative;
       z-index: 100;
    }

    .nav-item a {
       font: var(--font-ui);
       text-decoration: none;
       color: #333333;
       transition: color 0.2s ease;
    }

    .nav-item.active a {
       color: var(--primary); 
       font-weight: bold;
    }

    .nav-menu a {
        font: var(--font-ui);
        color: var(--text);
        font-weight: 500;
        font-size: 15px;
        transition: color .25s ease, opacity .25s ease;
    }

    .nav-menu a:hover, .nav-menu a[aria-current="page"] {
        color: var(--primary);
    }
    .nav-right {
        display: flex;
        align-items: center;
        gap: 20px;
    }

    .search-box {
        display: flex;
        align-items: center;
        background-color: var(--surface-alt);
        border: 1px solid var(--border);
        border-radius: 30px;
        padding: 6px 16px;
        gap: 10px;
    }
    .search-box svg {
        color: var(--text-light);
        display: flex;
    }
    .search-box input {
        font: var(--font-ui);
        border: none;
        background: transparent;
        outline: none;
        font-size: 14px;
        color: var(--text);
    }
    .subscribe-btn {
        font: var(--font-ui);
        background-color: var(--primary);
        color: #ffffff;
        padding: 10px 24px;
        border-radius: 30px;
        font-weight: 600;
        font-size: 14px;
    }
    .subscribe-btn:hover {
        background-color: var(--primary-dark);
        transform: translateY(-1px);
    }

    .search-toggle {
        display:none;
    }

    .search-close{
            display:none;
        }
.nav-toggle {
    display:none;

    width:48px;
    height:48px;

    background:none;
    border:none;

    cursor:pointer;

    align-items:center;
    justify-content:center;

    flex-direction:column;

    gap:5px;

    padding:4px;

    z-index:1001;

    transition:var(--transition);
}
    .nav-toggle-line {
        width: 24px;
        height: 2px;
        background-color: var(--text);
        transition: var(--transition);
    }

    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(1) {
        transform: translateY(8px) rotate(45deg);
    }
    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(2) {
        opacity: 0;
    }
    .navbar.is-nav-open .nav-toggle .nav-toggle-line:nth-child(3) {
        transform: translateY(-8px) rotate(-45deg);
    }

    .h1,
    .h2,
    .h3,
    .h4,
    .h5,
    .h6 {
        font-family: inherit;
    }

    /* ==========================================================================
       HERO & FEATURED SECTION (GRID & FLEXBOX)
       ========================================================================== */

    .hero-title,
    .article-title,
    .section-header h2,
    .hero-spotlight h2,
    .hero-spotlight-content h2,
    .category-card h3,
    .editor-card h3,
    .article-card h3,
    .post-title,
    .post-body h2,
    .post-body h3,
    .post-body h4,
    .newsletter-box h2,
    .footer-title,
    .editorial-content h2,
    .editorial-content h3,
    .editorial-references h4,
    .comments h4,
    .author-card-info h4 {
        font-family: var(--font-heading);
    }

    .hero-title,
    .article-title,
    .post-title {
        letter-spacing: -0.02em;
    }

    .hero {
        padding: 64px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .hero-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 60px;
        align-items: center;
    }
    .hero-content {
        display: flex;
        flex-direction: column;
    }
    .hero-label {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1.5px;
        margin-bottom: 16px;
    }
    .hero-title {
        font-size: 52px;
        font-weight: 800;
        line-height: 1.15;
        color: var(--text);
        letter-spacing: -1.5px;
        margin-bottom: 24px;
    }
    .hero-description {
        font-size: 18px;
        color: var(--text-light);
        margin-bottom: 32px;
        max-width: 800px;
    }
    .hero-buttons {
        display: flex;
        gap: 16px;
        margin-bottom: 40px;
    }
    .btn {
        font: var(--font-ui);
        display: inline-block;
        padding: 14px 32px;
        border-radius: 30px;
        font-weight: 600;
        font-size: 15px;
        text-align: center;
    }
    .btn-primary {
        background-color: var(--primary);
        color: #ffffff;
    }
    .btn-primary:hover {
        background-color: var(--primary-dark);
        transform: translateY(-1.5px);
    }
    .btn-outline {
        border: 2px solid var(--border);
        color: var(--text);
    }
    .btn-outline:hover {
        background-color: var(--surface-alt);
        border-color: var(--text);
        transform: translateY(-1.5px);
    }

    .btn-secondary {
      background-color: var(--primary);
      display: inline-block;
      padding: 14px 32px;
      border: 2px solid var(--primary);
      border-radius: 30px;
      background: var(--surface);
      color: #ffffff;
      font-weight: 600;
      font-size: 15px;
      text-align: center;
      transition: all var(--transition-fast);
    }

    .btn-secondary:hover {
        background: var(--primary);
        border-color: var(--primary);
        color: #fff;
        transform: translateY(-1.5px);
    }

    .input,
    .textarea,
    .select,
    .button {
        font: var(--font-ui);
    }

    .hero-community {
        display: flex;
        align-items: center;
        gap: 16px;
    }

    .hero-actions {
        display: flex;
        gap: 16px;
        flex-wrap: wrap;
        align-items: center;
        margin-top: 32px;
    }

    .avatar-group {
        display: flex;
    }
    .avatar {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background-color: var(--text);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 700;
        font-size: 12px;
        border: 2px solid #ffffff;
        margin-left: -12px;
    }
    .avatar:first-child {
        margin-left: 0;
    }
    .hero-community p {
        font-size: 13px;
        color: var(--text-light);
    }

    .hero-spotlight {
        background-color: var(--surface-alt);
        border-radius: 20px;
        padding: 32px;
        border: 1px solid var(--border);
        display: flex;
        flex-direction: column;
        transition: var(--transition);
    }
    .hero-spotlight:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow-lg);
    }
    .hero-spotlight-image {
        height: 240px;
        background: var(--surface-alt);
        border-radius: 14px;
        margin-bottom: 24px;
        position: relative;
        overflow: hidden;
    }
    .hero-spotlight-overlay {
        position: absolute;
        top: 16px;
        left: 16px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 4px 14px;
        border-radius: 20px;
        font-size: 12px;
        font-weight: 700;
        text-transform: uppercase;
    }
    .hero-spotlight h2 {
        font-size: 24px;
        line-height: 1.3;
        margin-bottom: 12px;
        color: var(--text);
    }
    .hero-spotlight p {
        color: var(--text-light);
        font-size: 15px;
        margin-bottom: 24px;
    }
    .hero-spotlight-meta {
        display: flex;
        gap: 16px;
        font-size: 13px;
        color: var(--text-light);
        margin-bottom: 24px;
    }

    /* ==========================================================================
       UTILITY COMPONENTS & ZONES
       ========================================================================== */
    .ad-zone {
        padding: 24px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .ad-placeholder {
        text-align: center;
    }
    .ad-label {
        font-size: 11px;
        color: var(--text-light);
        text-transform: uppercase;
        letter-spacing: 1.5px;
        display: block;
        margin-bottom: 10px;
    }
    .ad-box {
        background-color: var(--surface-alt);
        border: 2px dashed var(--border);
        padding: 36px;
        font-size: 14px;
        color: var(--text-light);
        border-radius: 12px;
        font-weight: 500;
    }

    .announcement-bar {
        background-color: var(--text);
        color: #ffffff;
        padding: 12px 0;
        font-size: 14px;
    }
    .announcement-content {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 16px;
        flex-wrap: wrap;
    }
    .announcement-badge {
        background-color: var(--primary);
        padding: 3px 10px;
        border-radius: 6px;
        font-weight: 700;
        font-size: 11px;
        text-transform: uppercase;
    }
    .announcement-link {
        color: var(--primary);
        font-weight: 600;
        text-decoration: underline;
    }

    .quick-access {
        padding: 24px 0;
        background-color: var(--surface-alt);
        border-bottom: 1px solid var(--border);
    }
    .quick-access-wrapper {
        display: flex;
        align-items: center;
        gap: 12px;
        flex-wrap: wrap;
    }
    .quick-title {
        font-size: 15px;
        font-weight: 700;
        color: var(--text);
        text-transform: uppercase;
        letter-spacing: 1px;
        margin-right: 12px;
    }
    .quick-pill {
        background: var(--surface);
        border: 1px solid var(--border);
        padding: 8px 18px;
        border-radius: 24px;
        font-size: 13px;
        font-weight: 600;
        color: var(--text);
    }
    .quick-pill:hover {
        background-color: var(--primary);
        color: #ffffff;
        border-color: var(--primary);
    }

    .stats {
        padding: 36px 0;
        background: var(--surface);
        border-bottom: 1px solid var(--border);
    }
    .stats-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 24px;
    }
    .stat-card {
        text-align: center;
        padding: 16px;
    }
    .stat-card h2 {
        font-size: 42px;
        font-weight: 800;
        color: var(--primary);
        margin-bottom: 6px;
        letter-spacing: -1px;
    }
    .stat-card p {
        color: var(--text-light);
        font-size: 14px;
        font-weight: 600;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

    /* ==========================================================================
       SECTION WRAPPERS & GRIDS
       ========================================================================== */
    .section {
        padding: 56px 0;
    }
    .section-header {
        margin-bottom: 48px;
        max-width: 650px;
    }
    .section-header h2 {
        font-size: 36px;
        color: var(--text);
        letter-spacing: -1px;
        margin-bottom: 12px;
    }
    .section-header p {
        color: var(--text-light);
        font-size: 16px;
    }

    .category-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .category-card {
        background: var(--surface);
        padding: 36px;
        border-radius: 16px;
        border: 1px solid var(--border);
        display: flex;
        flex-direction: column;
        transition: var(--transition);
    }
    .category-card:hover {
        transform: translateY(-6px);
        box-shadow: var(--shadow-lg);
        border-color: rgba(255, 74, 87, 0.2);
    }
    .category-icon {
        background-color: var(--surface-alt);
        color: var(--primary);
        width: 54px;
        height: 54px;
        border-radius: 12px;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: 800;
        font-size: 14px;
        margin-bottom: 24px;
        border: 1px solid var(--border);
    }
    .category-card h3 {
        font-size: 20px;
        color: var(--text);
        margin-bottom: 12px;
    }
    .category-card p {
        color: var(--text-light);
        font-size: 15px;
        margin-bottom: 24px;
        flex-grow: 1;
    }
    .category-link {
        font-weight: 700;
        color: var(--primary);
        font-size: 14px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

    .featured-story {
        background-color: var(--surface-alt);
    }
    .featured-story-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 60px;
        align-items: center;
    }
    .hero-spotlight-image {
        height: 400px;
        background: var(--surface-alt);
        border-radius: 20px;
        position: relative;
        overflow: hidden;
    }

    .hero-spotlight-image-link {
      display: block;
      width: 100%;
      height: 100%;
    }

    .hero-spotlight-img {
      display: block;
      position: relative;
      z-index: 1;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
    .hero-spotlight-img:hover {
      transform: scale(1.05);
      transition: var(--transition);
    }

    .hero-spotlight-fallback {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, var(--surface-alt), #DCE7FF);
      color: var(--text-light);
      font-family: var(--font-heading);
      font-size: 26px;
      font-weight: 700;
      letter-spacing: -0.02em;
    }

    .hero-spotlight-badge {
        position: absolute;
        z-index: 2;
        top: 24px;
        left: 24px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 6px 16px;
        border-radius: 24px;
        font-weight: 700;
        font-size: 12px;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }
    .story-category {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1px;
        margin-bottom: 16px;
    }

    .hero-spotlight-content {
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: flex-start;
    }

    .hero-spotlight-content h2 {
        font-size: 40px;
        color: var(--text);
        margin-bottom: 20px;
        line-height: 1.2;
        letter-spacing: -1px;
    }
    .hero-spotlight-content p {
        color: var(--text-light);
        margin-bottom: 28px;
        font-size: 16px;
        line-height: 1.7;
    }
    .hero-spotlight-meta {
        display: flex;
        gap: 16px;
        align-items: center;
        margin-bottom: 32px;
        color: var(--text-light);
        font-size: 14px;
    }



    /* Editors Picks Grid */
    .editors-picks {
        background: var(--surface);
    }
    .editors-picks .section-header {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        max-width: none;
    }
    .section-label {
        color: var(--primary);
        font-weight: 700;
        text-transform: uppercase;
        font-size: 13px;
        letter-spacing: 1px;
        margin-bottom: 8px;
    }
    .editor-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
        counter-reset: editor-card;
    }
    .editor-card {
        display: flex;
        gap: 24px;
        padding: 24px;
        border-radius: 16px;
        border: 1px solid var(--border);
        transition: var(--transition);
        counter-increment: editor-card;
    }
    .editor-card:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow);
    }
    .editor-number {
        font-size: 36px;
        font-weight: 800;
        color: var(--border);
        line-height: 1;
    }
    .editor-number::before {
        content: counter(editor-card, decimal-leading-zero);
    }
    .editor-category {
        color: var(--primary);
        font-weight: 700;
        font-size: 11px;
        text-transform: uppercase;
        margin-bottom: 6px;
        letter-spacing: 0.5px;
    }
    .editor-card h3 {
        font-size: 18px;
        margin-bottom: 10px;
        line-height: 1.4;
        color: var(--text);
    }
    .editor-card h3 a {
        color: inherit;
        text-decoration: none;
    }
    .editor-card h3 a:hover {
        color: var(--primary);
    }
    .editor-card p {
        font-size: 14px;
        color: var(--text-light);
        align-self: flex-start;
    }

    .editor-card-link {
        display: flex;
        align-items: flex-start;
        gap: 20px;
        width: 100%;
        height: 100%;
        color: inherit;
        text-decoration: none;
    }

    .editor-content {
        flex: 1;
        display: flex;
        flex-direction: column;
        align-self: stretch;
        min-width: 0;
    }

    .editor-image {
        width: 84px;
        height: 84px;
        flex-shrink: 0;
        overflow: hidden;
        border-radius: 12px;
        background: var(--surface-alt);
    }

    .editor-image img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform .35s ease;
    }

    .editor-card:hover .editor-image img {
        transform: scale(1.05);
    }

    .editor-header {
        display: flex;
        align-items: flex-start;
        gap: 18px;
        margin-bottom: 18px;
    }

    .editor-title {
        margin: 0;
        margin-bottom: 8px;
        font-size: 1.15rem;
        line-height: 1.35;
        font-weight: 700;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
    }

    .editor-meta {
        display: flex;
        align-items: center;
        gap: 10px;
        margin: 6px 0 8px;
    }

    .editor-snippet {
        margin: 0;
        margin-top: 12px;
        color: var(--text-light);
        line-height: 1.7;
        display: -webkit-box;
        -webkit-line-clamp: 4;
        -webkit-box-orient: vertical;
        overflow: hidden;
        flex-grow: 0;
    }

    /* Latest Articles Grid */
    .flex-between {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
    }
    .mb-5 {
        margin-bottom: 40px;
    }
    .article-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .article-card {
        display: flex;
        flex-direction: column;
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 20px;
        overflow: hidden;
        transition: var(--transition);
    }

    .article-card:hover {
        transform: translateY(-4px);
        box-shadow: var(--shadow-lg);
    }
    .article-image {
        height: 220px;
        background: var(--surface-alt);
        position: relative;
        overflow: hidden;
        transition: transform .35s ease;
    }

    .article-card:hover .article-image img{
        transform: scale(1.03);
    }
    .article-badge {
        position: absolute;
        top: 16px;
        left: 16px;
        background-color: var(--primary);
        color: #ffffff;
        padding: 4px 12px;
        border-radius: 20px;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
    }
    .article-content {
        padding: 28px;
        display: flex;
        flex-direction: column;
        flex-grow: 1;
        gap: 16px;
    }
    .article-meta {
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: .9rem;
        color: var(--text-light);
    }
    .article-card h3 {
        margin: 0;
        font-size: 1.7rem;
        line-height: 1.3;
        font-weight: 700;
    }
    .article-card p {
        margin: 0;
        color: var(--text-light);
        line-height: 1.8;
    }
    .article-link {
        margin-top: auto;
        font-weight: 700;
        color: var(--primary);
        text-decoration: none;
    }

    .article-link:hover {
        text-decoration: underline;
    }

    /* ==========================================
   ARTICLE HERO
========================================== */
.article-hero {
    padding: 32px 0 16px;
}

.article-header {
    max-width: var(--max-width);
    margin: 0 auto 1.5rem;
    padding: 0 24px;
}

.article-eyebrow {
    display: inline-block;
    margin-bottom: 10px;
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--primary);
}

.article-title {
    margin: 0;
    font-size: clamp(2.6rem, 5vw, 4rem);
    line-height: 1.08;
    font-weight: 800;
    letter-spacing: -0.02em;
    color: var(--text);
}

.article-summary {
    margin-top: 1.5rem;
    margin-bottom: 2rem;
    max-width: 720px;
    font-size: 1.2rem;
    line-height: 1.8;
    font-weight: 400;
    color: var(--text-light);
}

.article-meta time,
.article-meta span {
    display: inline-flex;
    align-items: center;
}

    /* ==========================================================================
       DYNAMIC BLOGGER WRAPPER STYLES & COMMENTS DESIGN SYSTEM
       ========================================================================== */
    .blog-posts {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
    }
    .post-outer {
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 16px;
        overflow: hidden;
        transition: var(--transition);
    }
    .post-outer:hover {
        transform: translateY(-5px);
        box-shadow: var(--shadow-lg);
    }

    /* Single Post Page Styles */
    .post-container {
        max-width: 800px;
        margin: 0 auto;
        background: var(--surface);
        padding: 72px 80px;
        border-radius: 16px;
        border: 1px solid var(--border);
    }
    .post-title {
        font-size: 42px;
        color: var(--text);
        margin-bottom: 24px;
        line-height: 1.2;
    }
    .post-body {
        font-size: 17px;
        line-height: 1.8;
        color: var(--text);
    }
    .post-body::after {
        content: "";
        display: block;
        clear: both;
    }
    .post-body img {
        border-radius: 12px;
        margin: 8px 32px 24px 0;
        float: left;
        max-width: 50%;
        height: auto;
    }
    .post-body h2 {
        margin: 40px 0 1.5rem;
        color: var(--text);
    }
    .post-body h3 {
        margin: 3rem 0 1.25rem;
        color: var(--text);
    }
    .post-body h4 {
        margin: 2.25rem 0 1rem;
        color: var(--text);
    }
    .post-body p {
        margin-bottom: 20px;
    }
    .post-body ul, .post-body ol {
        margin: 16px 0;
        padding-left: 24px;
    }
    .post-body li {
        margin-bottom: 8px;
    }
    .post-body a {
        color: var(--primary);
        text-decoration: underline;
    }
    .post-body blockquote {
        border-left: 4px solid var(--primary);
        padding-left: 20px;
        margin: 24px 0;
        color: var(--text-light);
        font-style: italic;
    }
    .post-body pre {
        background: var(--surface-alt);
        padding: 20px;
        border-radius: 8px;
        overflow-x: auto;
        margin: 20px 0;
    }
    .post-body code {
        background: var(--surface-alt);
        padding: 2px 6px;
        border-radius: 4px;
        font-size: 0.9em;
    }
/* ==========================================================================
   PHOENIX HOME HERO
   ========================================================================== */

.home-hero{
    padding:4rem 0 3rem;
}

.home-hero__content{
    max-width:760px;
}

.home-hero__eyebrow{
    display:inline-block;
    margin-bottom:1rem;
    font-size:.85rem;
    font-weight:700;
    letter-spacing:.12em;
    text-transform:uppercase;
    color:var(--primary);
}

.home-hero__title{
    font-size:clamp(2.5rem,5vw,4rem);
    line-height:1.1;
    font-weight:800;
    margin-bottom:1.5rem;
    letter-spacing:-.03em;
}

.home-hero__description{
    max-width:680px;
    font-size:1.2rem;
    line-height:1.8;
    color:var(--text-light);
    margin-bottom:2rem;
}

.home-hero__actions{
    display:flex;
    gap:1rem;
    flex-wrap:wrap;
}
    /* Author Card Styling */

    .author-card-avatar {
        width: 64px;
        height: 64px;
        border-radius: 50%;
        background: var(--primary);
        color: #ffffff;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 22px;
        font-weight: 700;
        flex-shrink: 0;
    }
    .author-card-info h4 {
        font-size: 18px;
        color: var(--text);
        margin-bottom: 6px;
    }
    .author-card-info p {
        font-size: 14px;
        color: var(--text-light);
        margin: 0;
        line-height: 1.6;
    }

    /* Comments Section Styling Integration */
    .comments-section-wrap {
        margin-top: 48px;
        background: var(--surface);
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 40px;
    }
    .comments h4 {
        font-size: 24px;
        color: var(--text);
        margin-bottom: 24px;
    }
    #comments-block {
        list-style: none;
        padding: 0;
        margin: 0;
    }
    .comment-author {
        font-weight: 600;
        color: var(--text);
        margin-bottom: 8px;
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 15px;
    }
    .comment-author a {
        color: var(--primary);
    }
    .comment-body {
        background: var(--surface-alt);
        padding: 16px 20px;
        border-radius: 12px;
        margin-bottom: 12px;
        color: var(--text);
        font-size: 15px;
        border: 1px solid var(--border);
    }
    .comment-footer {
        font-size: 13px;
        color: var(--text-light);
        margin-bottom: 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
    }
    .comment-footer a {
        color: var(--text-light);
    }
    .comment-footer a:hover {
        color: var(--primary);
    }
    .comment-form {
        margin-top: 32px;
        padding-top: 24px;
        border-top: 1px solid var(--border);
    }
    .comment-form h4 {
        font-size: 20px;
        color: var(--text);
        margin-bottom: 12px;
    }
    .comment-form p {
        color: var(--text-light);
        font-size: 14px;
        margin-bottom: 16px;
    }
    #comment-editor {
        background: var(--surface-alt);
        border-radius: 12px;
        border: 1px solid var(--border);
        min-height: 250px;
        width: 100%;
    }

    /* Static Page Styles */
    .static-page-container {
        width: min(1200px, calc(100% - 48px));
        margin: 0 auto;
        background: var(--surface);
        padding: 64px;
        border-radius: 20px;
        border: 1px solid var(--border);
    }

    /* ==========================================================================
       NEWSLETTER BOX
       ========================================================================== */
    .newsletter {
        background-color: var(--text);
        color: #ffffff;
        padding: 72px 0;
    }
    .newsletter-box {
        text-align: center;
        max-width: 640px;
        margin: 0 auto;
    }
    .newsletter-box h2 {
        font-size: 38px;
        font-weight: 800;
        letter-spacing: -1px;
        margin-bottom: 16px;
    }
    .newsletter-text {
        font-size: 16px;
        margin-bottom: 36px;
        color: rgba(255, 255, 255, 0.8);
    }
    .newsletter-form {
        display: flex;
        gap: 16px;
    }
    .newsletter-input {
        flex-grow: 1;
        padding: 16px 28px;
        border-radius: 30px;
        border: 1px solid rgba(255,255,255,0.1);
        outline: none;
        font: var(--font-ui);
        font-size: 15px;
        background: rgba(255, 255, 255, 0.05);
        color: white;
        transition: var(--transition);
    }
    .newsletter-input:focus {
        border-color: var(--primary);
        background: rgba(255, 255, 255, 0.1);
    }

    /* ==========================================================================
       FOOTER (GRID & FLEXBOX SYSTEM)
       ========================================================================== */
    .site-footer {
        background: var(--secondary-color);
        color: rgba(255, 255, 255, 0.72);
        padding: 64px 0 32px;
    }
    .footer-container {
        max-width: var(--max-width);
        margin: 0 auto;
        padding: 0 24px;
    }
    .footer-top {
        display: grid;
        grid-template-columns: 0.9fr 1.1fr;
        gap: 64px;
        margin-bottom: 48px;
    }
    .footer-brand {
        display: flex;
        flex-direction: column;
    }
    .footer-logo {
        font: var(--font-brand);
        font-size: 30px;
        font-weight: 800;
        letter-spacing: -0.03em;
        color: #ffffff;
        display: inline-block;
        margin-bottom: 16px;
    }
    .footer-logo span {
        color: var(--primary);
    }
    .footer-description {
        margin-bottom: 16px;
        font-size: 15px;
        line-height: 1.8;
        max-width: 340px;
    }
    .footer-tagline {
        font-size: 13px;
        line-height: 1.5;
        color: rgba(255, 255, 255, 0.45);
    }
    .footer-navigation {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 32px;
    }
    .footer-title {
        color: #ffffff;
        font-size: 0.9rem;
        font-weight: 700;
        margin-bottom: 24px;
        text-transform: uppercase;
        letter-spacing: .08em;
    }
    .footer-links {
        list-style: none;
    }
    .footer-links li {
        margin-bottom: 14px;
    }
    .footer-links a {
        font: var(--font-ui);
        font-size: 0.95rem;
        color: inherit;
    }
    .footer-links a:hover {
        color: var(--primary);
        transition: color 0.25s ease;
    }
    .footer-social {
        display: flex;
        flex-direction: column;
        gap: 12px;
    }
    .footer-social a {
        font-size: 14px;
    }
    .footer-social a:hover {
        color: var(--primary);
    }
    .footer-divider {
        border: none;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
        margin-bottom: 40px;
    }
    .footer-bottom {
        display: flex;
        justify-content: space-between;
        font-size: 14px;
        text-align: center;
        flex-direction: column;
        gap: 16px;
        align-items: center;
        padding-top: 0.5rem;
    }
    .footer-copyright strong {
        color: #ffffff;
    }
    .footer-credit a {
        color: #ffffff;
        font-weight: 600;
    }
    .footer-credit a:hover {
        color: var(--primary);
    }

    /* ==========================================================================
       RESPONSIVE GRID ADAPTIONS (MEDIA QUERIES)
       ========================================================================== */
    @media (max-width: 1024px) {
        .hero-grid {
            gap: 40px;
        }
        .hero-title {
            font-size: 42px;
        }
        .category-grid, .editor-grid, .article-grid {
            gap: 24px;
        }
    }

    @media (max-width: 900px) {
        .hero-grid, .featured-story-grid, .footer-top {
            grid-template-columns: 1fr;
            gap: 48px;
        }
        .stats-grid {
            grid-template-columns: repeat(2, 1fr);
        }
        .category-grid, .editor-grid, .article-grid {
            grid-template-columns: repeat(2, 1fr);
        }
        .footer-navigation {
            grid-template-columns: repeat(3, 1fr);
            gap: 20px;
        }
    }

    @media (max-width: 768px) {
        .navbar {
            padding: 12px 0;
        }
        .hero,
        .section {
            padding: 48px 0;
        }
        .stats {
            padding: 32px 0;
        }
        .newsletter {
            padding: 56px 0;
        }
        .site-footer {
            padding: 56px 0 28px;
        }
        .nav-toggle {
            display: flex;
            order:3;
        }
        .site-navigation {
            position:absolute;
            top:100%;
            left:0;
            right:0;

            background:#fff;

            border-top:1px solid var(--border);

            display:none;

            z-index:999;
        }

        .site-navigation
        .main-menu-section,
        .site-navigation
        .widget.PageList{

            width:100%;
        }


        .navbar.is-nav-open .site-navigation {
            display: block;
            position: absolute;
            top: 100%;
            left: 0;
            width: 100%;
            background: var(--surface);
            padding: 30px 24px;
            border-bottom: 1px solid var(--border);
            box-shadow: var(--shadow-lg);
        }
        .navbar.is-nav-open .nav-menu {
            flex-direction: column;
            gap: 20px;
        }
        .navbar.is-nav-open .nav-menu a {
            font-size: 18px;
            display: block;
        }
        .nav-right {
            gap:12px;
            display:flex;
            align-items:center;

        }
        .nav-right .search-box, .nav-right .subscribe-btn {
            display: none;
        }

        .category-grid,
        .editor-grid,
        .article-grid,
        .footer-navigation,
        .stats-grid,
        .blog-posts {
            grid-template-columns: 1fr;
            gap: 24px;
        }
        .hero-title {
            font-size: 36px;
        }
        .newsletter-form {
            flex-direction: column;
            gap: 12px;
        }
        .newsletter-input {
            width: 100%;
        }
        .post-container, .static-page-container {
            padding: 24px;
        }
        .post-title {
            font-size: 32px;
        }
        .post-body img {
            float: none;
            max-width: 100%;
            margin: 24px 0;
            display: block;
        }

        .home-hero{
            padding:2.5rem 0;
        }

        .home-hero__title {
            font-size:2.2rem;
        }

        .home-hero__description {
            font-size:1rem;
        }

        .home-hero__actions {
            flex-direction:column;
            align-items:stretch;
        }

        /* Latest Articles Header */
        .flex-between{
            flex-direction:column;
            align-items:flex-start;
            gap:1rem;
        }

        .flex-between .btn {
            margin-top: 0;
            align-self: flex-start;
        }

        .home-hero__actions .btn {
            width:100%;
        }

        .flex-between {
            flex-wrap: wrap;
            align-items: flex-start;
        }

        .flex-between h2 {
            margin: 0;
            width: 100%;
        }

        .flex-between .btn {
            margin-top: .5rem;
            align-self: flex-start;
        }

        .latest-articles-header {
            margin-bottom: 2rem;
        }

        /* Mobile Search Button */
        .search-toggle {
            display:flex;
            align-items:center;
            justify-content:center;
            width:44px;
            height:44px;
            border:none;
            background:transparent;
            cursor:pointer;
            font-size:22px;
            color:var(--text);
            flex-shrink:0;
            order:1;
        }

        .search-toggle:hover{
            color:var(--primary);
        }

        .search-box{
            display:none;
            order:2;
            position:relative;
        }

       .search-box.is-open{
            display:flex;
            align-items:center;
            flex:1;
            margin:0 12px;
        }

        .search-box.is-open input{
            width:100%;
        }

        .search-close{
            display:none;
            position:absolute;
            right:12px;
            top:50%;
            transform:translateY(-50%);
            border:none;
            background:transparent;
            font-size:22px;
            cursor:pointer;
            color:var(--text-light);
        }

        .search-box.is-open .search-close{
            display:block;
        }

        .search-box input{
            padding-right:36px;
        }


    }
 /* ==========================================================================
   PHOENIX MOBILE MENU
 ========================================================================== */


@media (max-width: 768px) {

    .site-navigation {

        display: none;

        position: absolute;
        top: 100%;
        left: 0;
        right: 0;

        background: var(--surface);

        border-top: 1px solid var(--border);

        box-shadow: var(--shadow-md);

        z-index: 1000;
    }

    .site-navigation.active {
        display: block;
    }

    .site-navigation .nav-menu {
        display: flex;
        flex-direction: column;
        gap: 0;
        padding: 1rem 0;
    }

    .nav-item a {
        display: block;
        padding: 1rem 1.5rem;
    }
}
/* ==========================================================================
   PHOENIX MOBILE NAVIGATION
   ========================================================================== */


.nav-toggle-line{

    width:24px;
    height:2px;

    background:var(--text);

    border-radius:999px;

    transition:var(--transition);

}

 /* ==========================================================================
   PHOENIX AUTHOR CARD
   ========================================================================== */

.author-card {
    max-width: var(--max-width);
    margin: 3rem auto;
    padding: 2rem;
    transition:var(--transition);
    background: var(--surface);
    border: 1px solid rgba(15, 23, 42, 0.04);
    border-radius: 28px;
    box-shadow: 0 14px 42px rgba(15, 23, 42, 0.08);
}

.author-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 24px 60px rgba(15,23,42,.12);

}

/* ==========================================================================
   HEADER
   ========================================================================== */

.author-card__header {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.author-card__avatar {
    width: 124px;
    height: 124px;
    flex-shrink: 0;
}

.author-card__avatar svg {
    display: block;
    width: 100%;
    height: 100%;
}

.author-card__identity {
    flex: 1;
}

.author-card__name {
    margin: 0 0 0.75rem;
    font-size: 2.2rem;
    font-weight: 800;
    color: var(--text);
    line-height: 1.1;
    letter-spacing: -0.02em;
}

/* ==========================================================================
   BADGE
   ========================================================================== */

.author-card__badge {
    display: inline-flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.55rem 1rem;
    border-radius: 999px;

    background: #E9F0FF;
    color: #3F4E73;

    font-size: 0.95rem;
    font-weight: 600;
}

.author-card__badge svg {
    width: 16px;
    height: 16px;
}

/* ==========================================================================
   BIO
   ========================================================================== */

.author-card__bio {
    margin-bottom: 2rem;
    padding:1.35rem 2rem;

    background: #F7F9FF;
    border: 1px solid #E8EDF9;
    border-radius: 999px;

    color: var(--text);

    font-size:1.18rem;
    font-weight:500;
    line-height: 1.65;
    text-align: center;
}

/* ==========================================================================
   ACTIONS
   ========================================================================== */

.author-card__actions {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 1rem;
}

.author-btn {
    display: flex;
    justify-content: center;
    align-items: center;

    height: 60px;
    padding: 0 1.5rem;

    border-radius: 999px;

    text-decoration: none;

    font: var(--font-ui);
    font-size: 1.05rem;
    font-weight: 700;

    transition: var(--transition);
}

.author-btn--secondary {
    background: var(--surface);
    color: var(--text);
    border: 1px solid var(--border);
}

.author-btn--secondary:hover {
    transform:translateY(-3px);
    box-shadow:var(--shadow-sm);
}

.author-btn--primary {
    background: var(--primary);
    color: #fff;
}

.author-btn--primary:hover {
    background: var(--primary-dark);
    transform: translateY(-3px);
    box-shadow:var(--shadow-md);
}

/* ==========================================================================
   RESPONSIVE
   ========================================================================== */

@media (max-width: 768px) {

    .author-card {
        padding: 1.5rem;
    }

    .author-card__header {
        flex-direction: column;
        text-align: center;
    }

    .author-card__name {
        font-size: 1.75rem;
    }

    .author-card__bio {
        padding: 1.4rem;
        border-radius: 22px;
        font-size: 1.05rem;
    }

    .author-card__actions {
        grid-template-columns: 1fr;
    }

}


/*==========================
 Buttons
==========================*/


.author-btn{

    display:flex;

    justify-content:center;

    align-items:center;

    text-decoration:none;

    padding:1rem;

    border-radius:999px;

    font-weight:600;

    transition:var(--transition);

}

/* Outline */



.author-btn-outline:hover{

    background:var(--surface-alt);

}

/* Primary */



.author-btn-primary:hover{

    transform:translateY(-2px);

    box-shadow:var(--shadow-md);

}

/*==========================
 Responsive
==========================*/

@media (max-width:768px){

.author-card{

    padding:2rem;

}






.author-actions{

    grid-template-columns:1fr;

}

}
    /* PHOENIX BLOG PAGER */
    .phoenix-pager {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-top: 2.5rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--border);
      width: 100%;
      box-sizing: border-box;
      font: var(--font-ui);
    }
    .phoenix-pager a {
      text-decoration: none;
      transition: all 0.2s ease-in-out;
    }
    .pager-nav-link {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      font-weight: 600;
      color: var(--text);
      padding: 10px 16px;
      background: var(--surface-alt);
      border-radius: 6px;
      border: 1px solid var(--border);
    }
    .pager-nav-link:hover {
      background: var(--surface);
      color: var(--primary);
      border-color: var(--primary);
    }
    .pager-home-link {
      font-weight: 500;
      font: var(--font-ui);
      color: var(--text-light);
      text-transform: uppercase;
      font-size: 0.85rem;
      letter-spacing: 0.5px;
    }
    .pager-home-link:hover {
      color: var(--primary);
    }
    .spacer {
      width: 140px;
    }
    .mobile-desktop-link {
      display: none; 
    }

    @media (max-width: 768px) {
      .phoenix-pager {
        flex-direction: column;
        gap: 1.5rem;
      }
      .pager-home-wrap {
        order: 3;
      }
      .spacer {
        display: none;
      }
    }

    /* SANAM EDITORIAL — Arabic-first visual layer */
    html[dir='rtl'] body { direction: rtl; text-align: right; }
    html[dir='rtl'] .navbar, html[dir='rtl'] .nav-container,
    html[dir='rtl'] .nav-menu, html[dir='rtl'] .nav-right,
    html[dir='rtl'] .post-footer, html[dir='rtl'] .blog-pager {
      direction: rtl;
    }
    html[dir='rtl'] .search-box input,
    html[dir='rtl'] input, html[dir='rtl'] textarea { text-align: right; }
    html[dir='rtl'] .nav-menu { padding-inline: 0; }
    html[dir='rtl'] .nav-item:first-child { margin-inline-start: 0; }
    html[dir='rtl'] .post-body, html[dir='rtl'] .post-content { line-height: 2; }
    html[dir='rtl'] .container { direction: rtl; }
    .navbar { border-bottom: 1px solid var(--border-color); }
    .logo { letter-spacing: 0; }
    .subscribe-btn { background: #9A7847; border-color: #9A7847; }
    .subscribe-btn:hover { background: #765A34; }
    .post-title, .entry-title, .widget-title { letter-spacing: 0; }
    @media (max-width: 768px) {
      html[dir='rtl'] .nav-right { margin-inline-start: auto; }
    }

    /* =========================================================
       SANAM EDITORIAL / ARABIC MAGAZINE DESIGN SYSTEM
       ========================================================= */
    :root {
      --max-width: 1280px;
      --primary-color: #967447;
      --primary-dark: #765a34;
      --bg-color: #f6f5f2;
      --card-bg: #ffffff;
      --text-color: #20201e;
      --text-muted: #77756f;
      --border-color: #e8e5df;
      --shadow: 0 8px 28px rgba(30, 27, 20, .055);
      --shadow-lg: 0 18px 48px rgba(30, 27, 20, .09);
    }
    html { scroll-behavior: smooth; }
    html[dir='rtl'] body { direction: rtl; text-align: right; }
    html[dir='rtl'] .navbar, html[dir='rtl'] .nav-container,
    html[dir='rtl'] .nav-menu, html[dir='rtl'] .nav-right,
    html[dir='rtl'] .post-footer, html[dir='rtl'] .blog-pager,
    html[dir='rtl'] .footer-top { direction: rtl; }
    html[dir='rtl'] .search-box input, html[dir='rtl'] input,
    html[dir='rtl'] textarea { text-align: right; }
    html[dir='rtl'] .container { direction: rtl; }
    body { background: #f6f5f2; color: #20201e; font-family: 'IBM Plex Sans Arabic', sans-serif; }
    .navbar {
      position: sticky; top: 0; padding: 12px 0;
      background: rgba(255,255,255,.96); backdrop-filter: blur(16px);
      border-bottom: 1px solid #e8e5df; box-shadow: 0 2px 16px rgba(20,20,20,.025);
    }
    .nav-container { min-height: 58px; gap: 28px; }
    .logo, .footer-logo { font-family: 'Tajawal', sans-serif; letter-spacing: 0; font-weight: 800; }
    .logo { font-size: 29px; }
    .nav-menu { gap: 1.65rem; }
    .nav-item a { font-size: 14px; font-weight: 600; color: #4a4945; }
    .nav-item a:hover, .nav-item a[aria-current='page'] { color: #967447; }
    .search-box { border-radius: 5px; }
    .subscribe-btn, .btn-primary {
      background: #967447; border-color: #967447; border-radius: 5px;
      color: #fff; box-shadow: none;
    }
    .subscribe-btn:hover, .btn-primary:hover { background: #765a34; }
    .btn, .btn-outline { border-radius: 5px; }
    .hero {
      padding: 74px 0 68px; background: #efede7;
      border-bottom: 1px solid #e5e1d8;
    }
    .hero-grid { grid-template-columns: 1fr .92fr; gap: clamp(28px,5vw,76px); }
    .hero-label, .section-label, .story-category {
      color: #967447; letter-spacing: 0; font-size: 13px; font-weight: 700;
    }
    .hero-title {
      font-family: 'Tajawal', sans-serif; font-size: clamp(38px,5vw,62px);
      line-height: 1.22; letter-spacing: 0; max-width: 700px;
      margin-bottom: 20px;
    }
    .hero-description { font-size: 17px; line-height: 2; max-width: 620px; color: #66635d; }
    .hero-buttons { margin-top: 10px; }
    .hero-spotlight {
      padding: 0; overflow: hidden; border: 0; border-radius: 6px;
      background: #fff; box-shadow: 0 14px 42px rgba(40,35,25,.09);
    }
    .hero-spotlight-image { height: 300px; border-radius: 0; margin: 0; }
    .hero-spotlight-content { padding: 28px 32px 32px; }
    .hero-spotlight h2 { font-family: 'Tajawal', sans-serif; font-size: 27px; line-height: 1.4; }
    .hero-spotlight p { line-height: 1.9; }
    .quick-access { padding: 22px 0; background: #fff; border-bottom: 1px solid #e8e5df; }
    .quick-access-wrapper { display:flex; flex-wrap:wrap; align-items:center; gap: 12px; }
    .quick-title { font-size: 14px; margin: 0 10px 0 6px; color:#77756f; }
    .quick-pill { border:1px solid #e8e5df; background:#fff; border-radius:3px; padding:8px 16px; font-size:13px; }
    .quick-pill:hover { border-color:#967447; color:#967447; }
    .stats { padding: 30px 0; background:#fff; }
    .stats-grid { border:1px solid #e8e5df; border-radius:5px; overflow:hidden; }
    .stat-card { padding:22px 16px; }
    .stat-card h2 { color:#967447; font-size:23px; }
    .section { padding: 76px 0; }
    .section-header { margin-bottom: 34px; }
    .section-header h2, .section-header h2 a {
      font-family:'Tajawal',sans-serif; font-size:clamp(27px,3vw,38px);
      font-weight:800; letter-spacing:0; color:#20201e;
    }
    .section-header > div > p:last-child, .section-header > p { color:#77756f; line-height:1.9; }
    .category-grid { gap:16px; }
    .category-card {
      border:1px solid #e8e5df; border-radius:5px; padding:26px;
      background:#fff; transition:transform .25s ease, box-shadow .25s ease, border-color .25s ease;
    }
    .category-card:hover { transform:translateY(-4px); border-color:#c9b99e; box-shadow:var(--shadow); }
    .category-icon { background:#f2eee7; color:#967447; border-radius:4px; }
    .category-card h3 { font-family:'Tajawal',sans-serif; font-size:20px; }
    .editors-picks { background:#efede7; }
    .editor-grid { gap:16px; }
    .editor-card { background:#fff; border:1px solid #e8e5df; border-radius:5px; padding:18px; }
    .editor-number { color:#c9b99e; }
    .editor-image { border-radius:4px; }
    .article-grid { gap:22px; }
    .article-card, .post-outer {
      border:1px solid #e8e5df; border-radius:5px; box-shadow:none;
      background:#fff;
    }
    .article-card:hover, .post-outer:hover { transform:translateY(-4px); box-shadow:var(--shadow); }
    .article-image { height:235px; }
    .article-content { padding:24px; }
    .article-card h3, .post-title, .entry-title {
      font-family:'Tajawal',sans-serif; letter-spacing:0; line-height:1.45;
    }
    .post-container {
      max-width:860px; border:0; border-radius:0; box-shadow:none;
      padding:clamp(24px,6vw,76px); margin:32px auto;
    }
    .post-title { font-size:clamp(32px,5vw,48px); }
    .post-body { font-size:18px; line-height:2.05; }
    .post-body img { border-radius:5px; }
    .post-body blockquote { border-right:3px solid #967447; border-left:0; background:#f6f5f2; padding:18px 22px; }
    .newsletter { background:#24231f; padding:64px 0; }
    .newsletter-box { max-width:780px; margin:auto; text-align:center; }
    .newsletter-box h2, .newsletter-text { color:#fff; }
    .newsletter-text { opacity:.72; }
    .newsletter-input { border-radius:4px; }
    .site-footer { background:#1c1b18; color:#f5f3ee; }
    .footer-description, .footer-tagline { color:#aaa69e; }
    .footer-title { color:#fff; }
    .footer-links a { color:#c8c4bb; }
    .blog-pager a { border-radius:4px; }
    @media (max-width: 900px) {
      .hero-grid { grid-template-columns:1fr; gap:34px; }
      .hero { padding:48px 0; }
      .hero-spotlight-image { height:260px; }
      .nav-container { flex-wrap:wrap; }
    }
    @media (max-width: 640px) {
      .container { padding-left:18px; padding-right:18px; }
      .hero-title { font-size:37px; }
      .hero-description { font-size:15px; }
      .hero-buttons { flex-wrap:wrap; }
      .hero-spotlight-content { padding:22px; }
      .section { padding:48px 0; }
      .post-container { margin:0; padding:28px 20px; }
      .post-body { font-size:17px; }
      .editor-card { padding:14px; }
      .editor-image { width:72px; height:72px; }
    }


    /* =========================================================
       SANAM EDITORIAL — REFINED LAYOUT & RESPONSIVE PASS
       ========================================================= */
    :root {
      --max-width: 1240px;
      --primary-color: #8b6b3f;
      --primary-dark: #6f512d;
      --bg-color: #f5f4f1;
      --card-bg: #ffffff;
      --text-color: #24231f;
      --text-muted: #77736b;
      --border-color: #e7e3dc;
      --surface-shadow: 0 12px 34px rgba(34, 30, 22, .055);
      --section-space: clamp(52px, 6vw, 84px);
    }
    body {
      font-family: 'IBM Plex Sans Arabic', sans-serif;
      font-size: 16px;
      line-height: 1.85;
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }
    .container { width: min(100% - 48px, var(--max-width)); padding-inline: 0; }
    .navbar { z-index: 1000; }
    .nav-container { min-height: 66px; gap: clamp(14px, 2.2vw, 30px); }
    .logo { display: inline-flex; align-items: center; min-height: 44px; line-height: 1.2; }
    .nav-menu { gap: clamp(14px, 1.8vw, 26px); }
    .nav-item a { display: inline-flex; align-items: center; min-height: 42px; }
    .nav-right { gap: 12px; }
    .search-box { min-height: 42px; padding: 5px 13px; }
    .search-box input { min-width: 120px; }
    .subscribe-btn, .btn { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; }
    .hero { padding-block: clamp(48px, 6vw, 76px); }
    .hero-grid { grid-template-columns: minmax(0, 1.08fr) minmax(320px, .92fr); gap: clamp(28px, 5vw, 68px); }
    .hero-content { min-width: 0; }
    .hero-title { max-width: 13ch; font-size: clamp(36px, 4.4vw, 58px); line-height: 1.3; }
    .hero-description { max-width: 58ch; font-size: clamp(15px, 1.25vw, 17px); line-height: 2.05; }
    .hero-buttons { flex-wrap: wrap; margin-bottom: 28px; }
    .hero-note-mark {
      width: 42px; height: 42px; flex: 0 0 42px; display: grid; place-items: center;
      border: 1px solid #d9cfbd; border-radius: 50%; color: var(--primary);
      background: #f7f4ee; font: 800 21px 'Tajawal', sans-serif;
    }
    .hero-community { gap: 12px; }
    .hero-community strong { display: block; font-size: 14px; line-height: 1.7; }
    .hero-community p { margin-top: 2px; }
    .hero-spotlight { align-self: stretch; }
    .hero-spotlight-image { height: clamp(220px, 24vw, 310px); }
    .hero-spotlight-fallback { background: #e9e5dc; color: #736b5e; }
    .hero-spotlight-content { padding: clamp(20px, 2.5vw, 30px); }
    .hero-spotlight-content h2 { font-size: clamp(22px, 2.2vw, 29px); line-height: 1.5; }
    .hero-spotlight-content p { line-height: 1.95; }
    .hero-spotlight-link { align-self: flex-start; color: var(--primary); font-weight: 700; border-bottom: 1px solid #cbb99c; padding-bottom: 3px; }
    .announcement-bar { padding-block: 10px; }
    .announcement-content { gap: 10px 14px; }
    .announcement-badge { border-radius: 3px; padding: 2px 9px; }
    .quick-access { padding-block: 18px; }
    .quick-access-wrapper { gap: 9px; }
    .quick-pill { min-height: 38px; display: inline-flex; align-items: center; }
    .stats { padding-block: 24px; }
    .stats-grid { grid-template-columns: repeat(4, minmax(0,1fr)); }
    .stat-card { padding: 18px 12px; }
    .section { padding-block: var(--section-space); }
    .section-header { margin-bottom: 30px; }
    .section-header h2 { line-height: 1.35; }
    .category-grid { grid-template-columns: repeat(3, minmax(0,1fr)); gap: 18px; }
    .category-card { min-height: 220px; padding: clamp(20px, 2.2vw, 28px); }
    .category-icon { width: 46px; height: 46px; margin-bottom: 18px; font-size: 12px; }
    .category-card h3 { line-height: 1.45; }
    .category-card p { margin-bottom: 16px; line-height: 1.85; }
    .featured-story-grid { grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: clamp(26px, 4vw, 56px); }
    .featured-story .hero-spotlight-image { height: clamp(280px, 34vw, 430px); }
    .hero-spotlight-img { object-fit: cover; }
    .editors-picks .section-header { align-items: center; }
    .editor-grid { grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px; }
    .editor-card { min-width: 0; padding: 16px; gap: 12px; }
    .editor-card-link { gap: 12px; }
    .editor-header { margin: 0; }
    .editor-image { width: 76px; height: 76px; }
    .editor-title { font-size: 16px; line-height: 1.55; }
    .editor-meta { gap: 7px; margin-block: 4px; }
    .editor-number { font-size: 22px; }
    .editor-snippet { margin-top: 7px; font-size: 13px; line-height: 1.75; -webkit-line-clamp: 3; }
    .article-grid, .blog-posts { grid-template-columns: repeat(3, minmax(0,1fr)); gap: 20px; }
    .article-card { min-width: 0; }
    .article-image { height: auto; aspect-ratio: 16 / 10; }
    .article-content { padding: 20px; gap: 11px; }
    .article-card h3 { font-size: clamp(17px, 1.6vw, 21px); line-height: 1.55; }
    .article-card p { font-size: 14px; line-height: 1.85; }
    .article-meta { font-size: 12px; }
    .article-link { padding-top: 4px; }
    .latest-articles-header { margin-bottom: 26px; }
    .latest-articles-header h2 { font: 800 clamp(26px, 3vw, 36px)/1.4 'Tajawal', sans-serif; }
    .article-page .article-hero { padding: clamp(32px, 5vw, 58px) 0 22px; }
    .article-header { max-width: 900px; }
    .article-title { max-width: 24ch; font-size: clamp(32px, 4.5vw, 54px); line-height: 1.35; }
    .article-summary { max-width: 68ch; font-size: 17px; line-height: 2; }
    .article-body-shell { padding: 22px 0 64px; }
    .article-body-shell > .container { max-width: 900px; }
    .article-body-shell .post-body {
      background: #fff; border: 1px solid var(--border); border-radius: 6px;
      padding: clamp(22px, 4vw, 54px); font-size: 18px; line-height: 2.15;
    }
    .post-body h2 { font-size: clamp(24px, 3vw, 32px); line-height: 1.5; margin: 2.2em 0 .7em; }
    .post-body h3 { font-size: clamp(21px, 2.5vw, 27px); line-height: 1.5; margin: 1.8em 0 .6em; }
    .post-body p { margin-bottom: 1.25em; }
    .post-body img { max-width: 100%; height: auto; margin: 1.5em auto; float: none; display: block; }
    .post-body figure { max-width: 100%; margin: 1.75em auto; }
    .post-body figcaption { color: var(--text-muted); font-size: 13px; text-align: center; margin-top: 8px; }
    .post-body ul, .post-body ol { padding-inline-start: 1.5em; padding-inline-end: 0; }
    html[dir='rtl'] .post-body blockquote { border-right: 3px solid var(--primary); border-left: 0; padding: 18px 22px; }
    html[dir='ltr'] .post-body blockquote { border-left: 3px solid var(--primary); border-right: 0; padding: 18px 22px; }
    .author-card { border-radius: 6px; box-shadow: none; border-color: var(--border); }
    .author-card__avatar { display: grid; place-items: center; border-radius: 50%; background: #f1eee8; color: var(--primary); font: 800 42px 'Tajawal', sans-serif; }
    .author-card__badge { background: #f4f1eb; border: 1px solid #e7e0d4; color: #6e5a3d; }
    .author-card__bio { border-radius: 5px; background: #f7f6f3; border-color: var(--border); text-align: right; font-size: 16px; }
    .comments-section-wrap { border-radius: 6px; padding: clamp(18px, 3vw, 34px); }
    .newsletter { padding-block: clamp(48px, 6vw, 72px); }
    .newsletter-box h2 { font-size: clamp(26px, 3vw, 36px); }
    .newsletter-form { max-width: 620px; margin: 24px auto 0; }
    .newsletter-input { min-height: 48px; }
    .site-footer { padding-block: 56px 24px; }
    .footer-top { gap: clamp(30px, 5vw, 70px); }
    .footer-navigation { gap: clamp(18px, 3vw, 42px); }
    .footer-links { display: grid; gap: 10px; }
    .footer-links a { display: inline-flex; padding-block: 2px; }
    .footer-bottom { text-align: center; }
    a:focus-visible, button:focus-visible, input:focus-visible {
      outline: 3px solid rgba(139,107,63,.32); outline-offset: 3px;
    }
    button, input { font: inherit; }
    .btn, .subscribe-btn, .quick-pill, .category-card, .article-card, .editor-card {
      transition: color .2s ease, background-color .2s ease, border-color .2s ease, box-shadow .2s ease, transform .2s ease;
    }
    html[dir='rtl'] .nav-menu { padding-inline: 0; }
    html[dir='rtl'] .quick-title { margin-inline: 0 8px; }
    html[dir='rtl'] .hero-spotlight-badge, html[dir='rtl'] .article-badge { right: 16px; left: auto; }
    html[dir='rtl'] .hero-spotlight-overlay { right: 16px; left: auto; }
    html[dir='rtl'] .article-body-shell .post-body { text-align: right; }
    html[dir='rtl'] .footer-navigation { direction: rtl; }
    @media (max-width: 1024px) {
      .nav-container { gap: 16px; }
      .nav-menu { gap: 14px; }
      .nav-item a { font-size: 13px; }
      .nav-right { gap: 8px; }
      .search-box input { min-width: 88px; width: 100px; }
      .category-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .editor-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .article-grid, .blog-posts { grid-template-columns: repeat(2, minmax(0,1fr)); }
    }
    @media (max-width: 768px) {
      .container { width: calc(100% - 36px); }
      .navbar { padding: 8px 0; }
      .nav-container { min-height: 54px; flex-wrap: nowrap; }
      .logo { font-size: 25px; }
      .nav-right { margin-inline-start: auto; }
      .nav-toggle { width: 42px; height: 42px; order: 3; }
      .search-toggle { order: 1; width: 42px; height: 42px; }
      .site-navigation, .site-navigation.active {
        position: absolute; top: 100%; inset-inline: 0; width: 100%;
        display: none; background: #fff; border-top: 1px solid var(--border);
        box-shadow: 0 18px 30px rgba(30,27,20,.10); padding: 8px 18px 16px;
        max-height: calc(100vh - 72px); overflow-y: auto;
      }
      .navbar.is-nav-open .site-navigation { display: block; }
      .navbar.is-nav-open .nav-menu { display: flex; flex-direction: column; gap: 0; padding: 0; }
      .navbar.is-nav-open .nav-item { border-bottom: 1px solid #f0ede7; }
      .navbar.is-nav-open .nav-menu a { display: flex; align-items: center; min-height: 48px; padding: 8px 4px; font-size: 16px; }
      .nav-right .subscribe-btn { display: none; }
      .search-box.is-open { position: absolute; z-index: 1002; inset-inline: 54px 48px; top: 5px; margin: 0; min-width: 0; }
      .search-box.is-open input { min-width: 0; width: 100%; }
      .hero { padding-block: 40px; }
      .hero-grid, .featured-story-grid { grid-template-columns: minmax(0,1fr); gap: 26px; }
      .hero-title { max-width: 100%; font-size: clamp(34px, 8vw, 44px); }
      .hero-description { font-size: 15px; }
      .hero-spotlight-image { height: clamp(210px, 58vw, 300px); }
      .hero-spotlight-content { padding: 20px; }
      .stats-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .stat-card { padding: 14px 8px; }
      .stat-card h2 { font-size: 24px; }
      .section { padding-block: 48px; }
      .section-header { margin-bottom: 22px; }
      .category-grid, .editor-grid, .article-grid, .blog-posts { grid-template-columns: minmax(0,1fr); gap: 14px; }
      .category-card { min-height: 0; padding: 20px; }
      .editor-card { padding: 14px; }
      .editor-image { width: 72px; height: 72px; }
      .article-image { aspect-ratio: 16 / 9; }
      .article-content { padding: 18px; }
      .article-card h3 { font-size: 19px; }
      .editors-picks .section-header { align-items: flex-start; flex-direction: column; gap: 14px; }
      .latest-articles-header { flex-direction: row; align-items: center; flex-wrap: wrap; gap: 12px; }
      .latest-articles-header h2 { width: auto; }
      .article-header { padding-inline: 0; }
      .article-title { font-size: clamp(30px, 8vw, 40px); }
      .article-summary { font-size: 15px; margin-block: 14px 18px; }
      .article-body-shell { padding-block: 8px 40px; }
      .article-body-shell .post-body { padding: 20px 18px; font-size: 16px; line-height: 2.05; }
      .author-card { margin: 28px 0; padding: 20px; }
      .author-card__header { flex-direction: row; text-align: right; gap: 14px; }
      .author-card__avatar { width: 60px; height: 60px; flex: 0 0 60px; font-size: 28px; }
      .author-card__name { font-size: 20px; }
      .author-card__bio { padding: 16px; font-size: 14px; }
      .author-card__actions { grid-template-columns: repeat(2,minmax(0,1fr)); }
      .author-btn { min-height: 48px; height: auto; padding: 10px; font-size: 14px; }
      .comments-section-wrap { margin-top: 28px; padding: 16px; }
      .newsletter { padding-block: 42px; }
      .newsletter-form { gap: 10px; }
      .newsletter-form .subscribe-btn { width: 100%; }
      .site-footer { padding-block: 42px 20px; }
      .footer-navigation { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 24px 18px; }
      .footer-brand { min-width: 0; }
      .footer-logo { font-size: 24px; }
      .footer-description { max-width: 42ch; }
    }
    @media (max-width: 420px) {
      .container { width: calc(100% - 28px); }
      .logo { font-size: 22px; }
      .hero-title { font-size: 33px; }
      .hero-buttons .btn { width: 100%; }
      .stats-grid { gap: 4px; }
      .stat-card h2 { font-size: 21px; }
      .footer-navigation { grid-template-columns: 1fr 1fr; }
      .author-card__actions { grid-template-columns: 1fr; }
    }
    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
    }

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
