body.script:
      //
      (function () {
        var toggle = document.querySelector('.nav-toggle');
        var navigation = document.getElementById('primary-navigation');
        var navbar = toggle && toggle.closest('.navbar');
        var searchToggle = document.querySelector('.search-toggle');
        var searchBox = document.querySelector('.search-box');
        var searchInput = searchBox && searchBox.querySelector('input');
        var searchClose = document.querySelector('.search-close');

        document.querySelectorAll('.hero-spotlight-image-link').forEach(function (link) {
          var fallback = link.querySelector('.hero-spotlight-fallback');
          var image = link.querySelector('.hero-spotlight-img');

          if (!fallback) {
            fallback = document.createElement('span');
            fallback.className = 'hero-spotlight-fallback';
            fallback.setAttribute('role', 'img');
            fallback.setAttribute('aria-label', 'Featured story image placeholder');
            fallback.textContent = 'موضوع مميز';
            link.insertBefore(fallback, link.firstChild);
          }

          if (image) {
            var hideBrokenImage = function () {
              image.style.display = 'none';
            };

            image.addEventListener('error', hideBrokenImage);
            if (image.complete && image.naturalWidth === 0) hideBrokenImage();
          }
        });

        if (!navbar || !toggle || !navigation) return;

        function setMenuState(isOpen) {
          navbar.classList.toggle('is-nav-open', isOpen);
          toggle.setAttribute('aria-expanded', String(isOpen));
          toggle.setAttribute('aria-label', isOpen ? 'إغلاق قائمة التنقل' : 'فتح قائمة التنقل');
          document.body.style.overflow = isOpen ? 'hidden' : '';
        }

        toggle.addEventListener('click', function () {
          setMenuState(toggle.getAttribute('aria-expanded') !== 'true');
        });

        navigation.addEventListener('click', function (event) {
          if (event.target.closest('a')) setMenuState(false);
        });

        document.addEventListener('keydown', function (event) {
          if (event.key === 'Escape') {
            setMenuState(false);
            toggle.focus();
          }
        });
        if (searchToggle && searchBox) {

    searchToggle.addEventListener('click', function () {


    searchBox.classList.toggle('is-open');
    searchToggle.style.display =
    searchBox.classList.contains('is-open') ? 'none' : 'flex';



    if (searchBox.classList.contains('is-open') && searchInput) {
        searchInput.focus();
        searchInput.select();
    }

});

}
if (searchClose) {

    searchClose.addEventListener('click', function () {

    if (searchInput) {
        searchInput.value = '';
    }

    searchBox.classList.remove('is-open');

    searchToggle.style.display = 'flex';

    searchInput.blur();

});

}
      }());
